-- Table: product_specific_list
DROP TABLE IF EXISTS `product_specific_list`;
CREATE TABLE `product_specific_list` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL,
  `branch_id` int(11) DEFAULT NULL,
  `color` varchar(50) DEFAULT NULL,
  `storage` varchar(50) DEFAULT NULL,
  `sim_configuration` varchar(50) DEFAULT NULL,
  `serial_number` varchar(100) DEFAULT NULL,
  `imei` varchar(50) DEFAULT NULL,
  `battery_health` int(11) DEFAULT NULL COMMENT 'Percentage 0-100',
  `manufacturer` varchar(100) DEFAULT NULL,
  `warranty_months` int(11) DEFAULT 0,
  `cost_price` decimal(10,2) DEFAULT NULL,
  `selling_price` decimal(10,2) DEFAULT NULL,
  `wholesale_price` decimal(10,2) DEFAULT NULL,
  `warranty_terms` text DEFAULT NULL,
  `condition` enum('New','Refurbished','Used') DEFAULT 'New',
  `trade_in_eligible` tinyint(1) DEFAULT 0,
  `status` enum('available','sold','returned','damaged','transferred') DEFAULT 'available',
  `sale_item_id` int(11) DEFAULT NULL COMMENT 'Links to sale_items when sold',
  `invoice_item_id` int(11) DEFAULT NULL COMMENT 'Links to invoice_items when invoiced',
  `refund_item_id` int(11) DEFAULT NULL COMMENT 'Links to refund_items when returned',
  `grn_item_id` int(11) DEFAULT NULL COMMENT 'Links to grn_items when received',
  `stock_take_item_id` int(11) DEFAULT NULL COMMENT 'Links to stock_take_items when added via stock take',
  `transfer_item_id` int(11) DEFAULT NULL COMMENT 'Links to transfer_items when transferred',
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `created_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_serial_number` (`serial_number`,`branch_id`),
  UNIQUE KEY `unique_imei` (`imei`,`branch_id`),
  KEY `idx_product_id` (`product_id`),
  KEY `idx_branch_id` (`branch_id`),
  KEY `idx_status` (`status`),
  KEY `idx_sale_item_id` (`sale_item_id`),
  KEY `idx_invoice_item_id` (`invoice_item_id`),
  KEY `idx_grn_item_id` (`grn_item_id`),
  KEY `idx_stock_take_item_id` (`stock_take_item_id`),
  KEY `idx_transfer_item_id` (`transfer_item_id`),
  KEY `idx_serial_number` (`serial_number`),
  KEY `idx_imei` (`imei`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: products
DROP TABLE IF EXISTS `products`;
CREATE TABLE `products` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `product_code` varchar(50) NOT NULL,
  `product_name` varchar(255) DEFAULT NULL,
  `category_id` int(11) DEFAULT NULL,
  `brand` varchar(100) DEFAULT NULL,
  `model` varchar(100) DEFAULT NULL,
  `color` varchar(20) DEFAULT NULL,
  `storage` varchar(50) DEFAULT NULL,
  `sim_configuration` varchar(50) DEFAULT NULL,
  `serial_number` varchar(100) DEFAULT NULL,
  `imei` varchar(50) DEFAULT NULL,
  `battery_health` int(11) DEFAULT NULL,
  `sku` varchar(100) DEFAULT NULL,
  `barcode` varchar(100) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `specifications` text DEFAULT NULL,
  `cost_price` decimal(10,2) DEFAULT 0.00,
  `selling_price` decimal(10,2) DEFAULT 0.00,
  `wholesale_price` decimal(10,2) DEFAULT NULL,
  `minimum_price` decimal(10,2) DEFAULT 0.00,
  `profit_margin` decimal(5,2) DEFAULT 0.00,
  `reorder_level` int(11) DEFAULT 10,
  `reorder_quantity` int(11) DEFAULT 10,
  `warranty_months` int(11) DEFAULT 0,
  `warranty_terms` text DEFAULT NULL,
  `condition` enum('New','Refurbished','Used') DEFAULT 'New',
  `status` enum('Active','Inactive','Discontinued') DEFAULT 'Active',
  `trade_in_eligible` tinyint(1) DEFAULT 0,
  `is_trade_in` tinyint(1) DEFAULT 0,
  `tags` varchar(255) DEFAULT NULL,
  `images` text DEFAULT NULL,
  `branch_id` int(11) DEFAULT NULL,
  `tax_id` int(11) DEFAULT NULL,
  `quantity_in_stock` int(11) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `created_by` int(11) DEFAULT NULL,
  `updated_by` int(11) DEFAULT NULL,
  `expiry_date` date DEFAULT NULL,
  `weight` decimal(10,3) DEFAULT NULL,
  `unit_of_measure` varchar(20) DEFAULT NULL,
  `manufacturer` varchar(100) DEFAULT NULL,
  `batch_number` varchar(100) DEFAULT NULL,
  `requires_specific_list` tinyint(1) DEFAULT 0 COMMENT '1 if product requires product_specific_list entries (smartphones, laptops, tablets, gaming devices)',
  `source` varchar(50) DEFAULT 'manual' COMMENT 'Source of product: manual, import, bulk, etc.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `product_code` (`product_code`),
  KEY `idx_product_code` (`product_code`),
  KEY `idx_category_id` (`category_id`),
  KEY `idx_branch_id` (`branch_id`),
  KEY `idx_status` (`status`),
  KEY `idx_is_trade_in` (`is_trade_in`),
  KEY `idx_tax_id` (`tax_id`),
  KEY `idx_requires_specific_list` (`requires_specific_list`),
  KEY `idx_wholesale_price` (`wholesale_price`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: proforma_terms
DROP TABLE IF EXISTS `proforma_terms`;
CREATE TABLE `proforma_terms` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  `content` text NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_is_active` (`is_active`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `proforma_terms` (`id`, `title`, `content`, `is_active`, `created_at`, `updated_at`) VALUES
('1', 'Standard Payment Terms', 'Payment is due within 30 days of invoice date. Late payments may incur interest charges at 2% per month. Goods remain the property of ELECTROX until full payment is received. All prices are in USD unless otherwise stated.', '1', '2026-02-03 16:08:55', '2026-02-03 16:08:55'),
('2', 'Cash on Delivery Terms', 'Payment must be made in full upon delivery. No credit terms apply. Cash or bank transfer accepted. Goods will not be released until payment is confirmed. All sales are final once payment is received.', '1', '2026-02-03 16:08:55', '2026-02-03 16:08:55'),
('3', 'Net 15 Payment Terms', 'Payment is due within 15 days of invoice date. Early payment discounts may apply if paid within 7 days. Returned goods must be in original condition and packaging. Warranty terms apply as per manufacturer specifications.', '1', '2026-02-03 16:08:55', '2026-02-03 16:08:55'),
('4', 'Proforma Invoice Terms', 'This is a proforma invoice and does not constitute a demand for payment. Goods will be dispatched upon receipt of payment. Prices are valid for 30 days from invoice date. All products are subject to availability. ELECTROX reserves the right to cancel orders if payment is not received within the specified timeframe.', '1', '2026-02-03 16:08:55', '2026-02-03 16:08:55');

-- Table: refund_items
DROP TABLE IF EXISTS `refund_items`;
CREATE TABLE `refund_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `refund_id` int(11) NOT NULL,
  `sale_item_id` int(11) NOT NULL,
  `product_id` int(11) NOT NULL,
  `product_name` varchar(255) NOT NULL,
  `quantity` int(11) NOT NULL DEFAULT 1,
  `unit_price` decimal(10,2) NOT NULL,
  `total_price` decimal(10,2) NOT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_refund_id` (`refund_id`),
  KEY `idx_sale_item_id` (`sale_item_id`),
  KEY `idx_product_id` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: refund_payments
